def transform(grid):
    h, w = len(grid), len(grid[0])

    hdiv = [r for r in range(h) if len(set(grid[r])) == 1]
    vdiv = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    divider = grid[hdiv[0]][0] if hdiv else grid[0][vdiv[0]]

    def sections(size, divs):
        result = []
        start = 0
        for p in divs:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    row_sections = sections(h, hdiv)
    col_sections = sections(w, vdiv)

    counts = {}
    for row in grid:
        for value in row:
            if value != divider:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find the compartment containing the most non-background marks.
    source = None
    best_count = 0
    for r0, r1 in row_sections:
        for c0, c1 in col_sections:
            marks = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != background
            ]
            if len(marks) > best_count:
                best_count = len(marks)
                source = marks

    out = [row[:] for row in grid]
    for r0, r1 in row_sections:
        for c0, c1 in col_sections:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = background
            if source:
                for dr, dc, color in source:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = color
    return out
